mapper.select:
SELECT item_id, category, name, description, price, status, reject_reason, sales_count, creator_id, asset_key, asset_url, asset_width, asset_height, placement_type, created_at, updated_at FROM item WHERE (status IS NULL OR status = 'ACTIVE')
AND category = #{category}
ORDER BY created_at DESC NULLS LAST, item_id DESC

SELECT acorn_balance
FROM users
WHERE user_id = #{userId}

mapper.update:
UPDATE users
SET acorn_balance = acorn_balance - #{price},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND acorn_balance >= #{price}
